// Standalone multicolor bitmap part. SYS entry is generated by KickAssembler.
.var picture = LoadBinary("assets/boygiana.koa")
.assert "Source is a standard Koala bitmap", picture.getSize(), 10003

.const SCREEN = $0400
.const BITMAP = $2000
.const SCREEN_DATA = BITMAP + 8000
.const COLOR_DATA = SCREEN_DATA + 1000
.const BACKGROUND = picture.get(10002) & $0f
.const TV_COLUMN = 22
.const TV_ROW = 3
.const TV_WIDTH = 10
.const TV_HEIGHT = 8
.const TV_UPDATE_RASTER = 144
.const SCROLL_FRAME_INTERVAL = 4
.const TILE_POINTER = $fb

* = $4800 "Terrain tiles and map"
    .import source "terrain.asm"

BasicUpstart2(start)

start:
    sei
    cld

    // Keep the display blank while copying the two color maps.
    lda #$0b
    sta $d011
    lda #0
    sta $d015
    sta $d01a
    sta $d020
    lda #$7f
    sta $dc0d
    sta $dd0d
    lda $dc0d
    lda $dd0d
    lda #$0f
    sta $d019

    // Select VIC bank 0 without changing the other CIA2 port bits.
    lda $dd02
    ora #3
    sta $dd02
    lda $dd00
    ora #3
    sta $dd00

    ldx #0
copyPages:
    .for (var page = 0; page < 3; page++) {
        lda SCREEN_DATA + page * $100,x
        sta SCREEN + page * $100,x
        lda COLOR_DATA + page * $100,x
        sta $d800 + page * $100,x
    }
    inx
    bne copyPages

    ldx #0
copyTail:
    lda SCREEN_DATA + $300,x
    sta SCREEN + $300,x
    lda COLOR_DATA + $300,x
    sta $db00,x
    inx
    cpx #232
    bne copyTail

    lda #$18
    sta $d018
    sta $d016
    lda #BACKGROUND
    sta $d021

    jsr initTerrain

    // Reveal the complete picture during the lower border.
waitBorder:
    lda $d011
    bpl waitBorder
    lda #$3b
    sta $d011
display:
    lda $d012
    cmp #TV_UPDATE_RASTER
    bne display
frameStart:
    dec scrollCountdown
    bne countFrame
    jsr scrollTerrain
    lda #SCROLL_FRAME_INTERVAL
    sta scrollCountdown
countFrame:
    inc frameCounter
    bne frameDone
    inc frameCounter+1
frameDone:
    // Short hold frames must leave raster 144 before polling for the next one.
!leaveRaster:
    lda $d012
    cmp #TV_UPDATE_RASTER
    beq !leaveRaster-
    jmp display

initTerrain:
    // Every TV cell uses black, brown, orange and green throughout scrolling.
    ldx #0
!colors:
    lda #$98
    .for (var row = 0; row < TV_HEIGHT; row++) {
        sta SCREEN + (TV_ROW + row) * 40 + TV_COLUMN,x
    }
    lda #$05
    .for (var row = 0; row < TV_HEIGHT; row++) {
        sta $d800 + (TV_ROW + row) * 40 + TV_COLUMN,x
    }
    inx
    cpx #TV_WIDTH
    bne !colors-

    // Forty incoming pixel columns replace the old TV image while blanked.
    jsr prepareColumn
    lda #TV_WIDTH * 4
    sta prefillLeft
!prefill:
    jsr scrollTerrain
    dec prefillLeft
    bne !prefill-
    rts

prepareColumn:
    // Map rows contain tile IDs; each ID selects eight packed bitmap bytes.
    ldx incomingTile
    .for (var row = 0; row < TV_HEIGHT; row++) {
        lda terrainMapStart + row * TERRAIN_MAP_WIDTH,x
        tay
        asl
        asl
        asl
        sta TILE_POINTER
        tya
        lsr
        lsr
        lsr
        lsr
        lsr
        clc
        adc #>terrainTiles
        sta TILE_POINTER+1
        ldy #0
        .for (var line = 0; line < 8; line++) {
            lda (TILE_POINTER),y
            sta incomingColumn + row * 8 + line
            .if (line < 7) {
                iny
            }
        }
    }
    rts

scrollTerrain:
    // Shift right-to-left twice. A retains the two incoming pixel bits while
    // carry propagates through the bitmap bytes; no second bitmap is needed.
    .for (var line = 0; line < TV_HEIGHT * 8; line++) {
        .var address = BITMAP + ((TV_ROW + floor(line / 8)) * 40 + TV_COLUMN) * 8 + (line & 7)
        lda incomingColumn + line
        asl
        .for (var column = TV_WIDTH - 1; column >= 0; column--) {
            rol address + column * 8
        }
        asl
        .for (var column = TV_WIDTH - 1; column >= 0; column--) {
            rol address + column * 8
        }
        // Keep the remaining source pixels ready for the next PAL frame.
        asl incomingColumn + line
        asl incomingColumn + line
    }

    inc tilePixelX
    lda tilePixelX
    cmp #4
    bne !done+
    lda #0
    sta tilePixelX
    inc incomingTile
    lda incomingTile
    and #TERRAIN_MAP_WIDTH - 1
    sta incomingTile
    jsr prepareColumn
!done:
    rts

frameCounter: .word 0
scrollCountdown: .byte SCROLL_FRAME_INTERVAL
incomingTile: .byte 0
tilePixelX: .byte 0
prefillLeft: .byte 0
incomingColumn: .fill TV_HEIGHT * 8, 0

.assert "Player fits below the bitmap", * <= BITMAP, true

* = BITMAP "Koala bitmap and color maps"
    .fill 10000, picture.get(i + 2)

.assert "Terrain height matches the TV", TERRAIN_MAP_HEIGHT, TV_HEIGHT
.assert "Map wraps with a bit mask", (TERRAIN_MAP_WIDTH & (TERRAIN_MAP_WIDTH - 1)), 0
.assert "Tile addresses start on a page boundary", <terrainTiles, 0
.assert "Tile IDs fit in a byte", TERRAIN_TILE_COUNT <= 256, true
